            cf2 = {delt(i, t, k): 1}
            rhs = 0.0
            for tau in range(max(0, t - lag_next), t):
                cf2[u(i, tau)] = 1
            for tau in range(t - lag_next, 0):  # pre-horizon treated as u0
                rhs += u0
            row(cf2, -np.inf, rhs)

