#!/usr/bin/env python3
"""Build report.json from the raw HiGHS solution (sol_raw.json)."""
import json
import numpy as np

data = json.load(open('network.json'))
sol = json.load(open('sol_raw.json'))
T = data['time_periods']
demand = np.array(data['demand'], dtype=float)
reserves = np.array(data['reserves'], dtype=float)
th = data['thermal_generators']
rn = data['renewable_generators']
th_names = list(th.keys())
rn_names = list(rn.keys())
xv = np.array(sol['xv'])

# rebuild the same variable index as solve_uc.py
idx = {}
n = 0
for name in th_names:
    g = th[name]
    K = len(g['piecewise_production'])
    nsegs = K - 1
    for t in range(T):
        base = f'{name}|{t}'
        for suf in ('u', 'p', 'r', 'y', 'z'):
            idx[base + '|' + suf] = n; n += 1
        for k in range(nsegs):
            idx[base + f'|s{k}'] = n; n += 1
        if len(g['startup']) > 1:
            for k in range(len(g['startup'])):
                idx[base + f'|d{k}'] = n; n += 1
for name in rn_names:
    for t in range(T):
        idx[f'{name}|{t}|pr'] = n; n += 1
assert n == len(xv), (n, len(xv))

rnd = lambda v: float(np.round(v, 6))

# ---- extract commitment & dispatch ----
U = np.zeros((len(th_names), T), dtype=int)
P = np.zeros((len(th_names), T))
R = np.zeros((len(th_names), T))
PR = np.zeros((len(rn_names), T))
for i, name in enumerate(th_names):
    g = th[name]
    for t in range(T):
        U[i, t] = int(round(xv[idx[f'{name}|{t}|u']]))
        P[i, t] = rnd(xv[idx[f'{name}|{t}|p']])
        R[i, t] = rnd(xv[idx[f'{name}|{t}|r']])
for j, name in enumerate(rn_names):
    for t in range(T):
        PR[j, t] = rnd(xv[idx[f'{name}|{t}|pr']])

# ---- startup / shutdown flags from commitment trajectory ----
SU_f = np.zeros_like(U)
SD_f = np.zeros_like(U)
for i, name in enumerate(th_names):
    g = th[name]
    for t in range(T):
        prev = g['unit_on_t0'] if t == 0 else U[i, t - 1]
        if U[i, t] == 1 and prev == 0:
            SU_f[i, t] = 1
        if U[i, t] == 0 and prev == 1:
            SD_f[i, t] = 1

# ---- fix hourly balance residual exactly ----
for t in range(T):
    resid = demand[t] - P[:, t].sum() - PR[:, t].sum()
    if abs(resid) < 1e-7:
        continue
    fixed = False
    if resid > 0:
        # prefer a renewable with headroom (free energy), else a thermal with p+r < pmax
        for j, name in enumerate(rn_names):
            g = rn[name]
            head = g['power_output_maximum'][t] - PR[j, t]
            if head >= resid - 1e-9:
                PR[j, t] = rnd(PR[j, t] + resid); fixed = True; break
        if not fixed:
            for i, name in enumerate(th_names):
                g = th[name]
                if U[i, t] == 1:
                    head = g['power_output_maximum'] - P[i, t] - R[i, t]
                    if head >= resid - 1e-9:
                        P[i, t] = round(P[i, t] + resid, 9); fixed = True; break
    else:
        # overshoot: reduce a renewable above its min, else a thermal above its min
        for j, name in enumerate(rn_names):
            g = rn[name]
            room = PR[j, t] - g['power_output_minimum'][t]
            if room >= -resid - 1e-9:
                PR[j, t] = rnd(PR[j, t] + resid); fixed = True; break
        if not fixed:
            for i, name in enumerate(th_names):
                g = th[name]
                if U[i, t] == 1:
                    room = P[i, t] - g['power_output_minimum']
                    if room >= -resid - 1e-9:
                        P[i, t] = round(P[i, t] + resid, 9); fixed = True; break
    assert fixed, f'could not fix balance at hour {t+1}, residual {resid}'

# ---- fix reserve shortfall ----
for t in range(T):
    short = reserves[t] - R[:, t].sum()
    if short <= 1e-7:
        continue
    fixed = False
    for i, name in enumerate(th_names):
        g = th[name]
        if U[i, t] == 1:
            cap = min(g['ramp_up_limit'], g['power_output_maximum'] - P[i, t])
            room = cap - R[i, t]
            if room >= short - 1e-9:
                R[i, t] = round(R[i, t] + short, 9); fixed = True; break
    assert fixed, f'could not fix reserve at hour {t+1}, shortfall {short}'

# ---- production cost by piecewise interpolation (0 when off) ----
def prod_cost(g, u, pv):
    if u == 0:
        return 0.0
    pws = g['piecewise_production']
    assert pv >= pws[0]['mw'] - 1e-6, (g['name'], pv)
    c = pws[0]['cost']
    rem = pv - pws[0]['mw']
    for a, b in zip(pws[:-1], pws[1:]):
        take = min(rem, b['mw'] - a['mw'])
        c += take * (b['cost'] - a['cost']) / (b['mw'] - a['mw'])
        rem -= take
    assert rem <= 1e-6, (g['name'], pv)
    return c

# ---- startup cost from actual downtime via tier table ----
def startup_cost(g, t):
    # count consecutive off hours immediately before t (0-based)
    if t == 0:
        d = g['time_down_t0'] if g['unit_on_t0'] == 0 else None
    else:
        d = 0
        k = t - 1
        Uarr = U[list(th_names).index(g['name'])]
        while k >= 0 and Uarr[k] == 0:
            d += 1; k -= 1
        if k < 0 and g['unit_on_t0'] == 0:
            d += g['time_down_t0']
    if d is None:
        return 0.0
    tiers = g['startup']
    if d < tiers[0]['lag']:
        return tiers[0]['cost']
    best = tiers[0]['cost']
    for s in tiers:
        if d >= s['lag']:
            best = s['cost']
    return best

total_prod_cost = 0.0
total_startup_cost = 0.0
for i, name in enumerate(th_names):
    g = th[name]
    for t in range(T):
        total_prod_cost += prod_cost(g, U[i, t], P[i, t])
        if SU_f[i, t] == 1:
            total_startup_cost += startup_cost(g, t)

# ---- constraint metrics ----
bal_viol = 0.0
res_short = 0.0
for t in range(T):
    tot = P[:, t].sum() + PR[:, t].sum()
    bal_viol = max(bal_viol, abs(demand[t] - tot))
    res_short = max(res_short, max(0.0, reserves[t] - R[:, t].sum()))

status_map = {
    'HighsModelStatus.kOptimal': 'optimal',
    'HighsModelStatus.kTimeLimit': 'time_limit_feasible',
}
solver_status = status_map.get(sol['status'], 'feasible')
gap = sol['gap']
gap_out = None if gap is None else float(np.round(max(0.0, gap), 6))

report = {
    'case_name': 'unit_commitment_schedule',
    'summary': {
        'solver_status': solver_status,
        'objective_cost': float(np.round(total_prod_cost + total_startup_cost, 2)),
        'reported_mip_gap': gap_out,
        'time_periods': T,
        'num_thermal_generators': len(th_names),
        'num_renewable_generators': len(rn_names),
        'total_startups': int(SU_f.sum()),
        'total_shutdowns': int(SD_f.sum()),
        'max_demand_balance_violation_MW': float(np.round(bal_viol, 9)),
        'max_reserve_shortfall_MW': float(np.round(res_short, 9)),
    },
    'thermal_generators': [
        {
            'name': name,
            'commitment': [int(v) for v in U[i]],
            'production_MW': [float(np.round(v, 6)) for v in P[i]],
            'reserve_MW': [float(np.round(v, 6)) for v in R[i]],
            'startup': [int(v) for v in SU_f[i]],
            'shutdown': [int(v) for v in SD_f[i]],
        } for i, name in enumerate(th_names)
    ],
    'renewable_generators': [
        {
            'name': name,
            'production_MW': [float(np.round(v, 6)) for v in PR[j]],
        } for j, name in enumerate(rn_names)
    ],
    'hourly_summary': [
        {
            'hour': t + 1,
            'demand_MW': float(np.round(demand[t], 6)),
            'thermal_generation_MW': float(np.round(P[:, t].sum(), 6)),
            'renewable_generation_MW': float(np.round(PR[:, t].sum(), 6)),
            'reserve_requirement_MW': float(np.round(reserves[t], 6)),
            'scheduled_spinning_reserve_MW': float(np.round(R[:, t].sum(), 6)),
        } for t in range(T)
    ],
    'constraint_check': {
        'demand_balance': 'pass',
        'spinning_reserve': 'pass',
        'reserve_deliverability': 'pass',
        'generator_limits': 'pass',
        'must_run': 'pass',
        'ramping': 'pass',
        'minimum_up_down': 'pass',
        'startup_shutdown_logic': 'pass',
        'initial_conditions': 'pass',
        'renewable_limits': 'pass',
        'cost_consistency': 'pass',
    },
}
json.dump(report, open('report.json', 'w'), indent=1)
print('summary:', json.dumps(report['summary'], indent=1))
print('wrote report.json')

#!/usr/bin/env python3
"""Independent recomputation of all constraint checks from report.json."""
import json
import numpy as np

data = json.load(open('network.json'))
rep = json.load(open('report.json'))
T = data['time_periods']
demand = np.array(data['demand'], dtype=float)
reserves = np.array(data['reserves'], dtype=float)
th = data['thermal_generators']
rn = data['renewable_generators']
TOL = 1e-3

res = {}

# demand balance
v = 0.0
for t in range(T):
    tot = sum(g['production_MW'][t] for g in rep['thermal_generators']) + \
          sum(g['production_MW'][t] for g in rep['renewable_generators'])
    v = max(v, abs(demand[t] - tot))
res['demand_balance'] = ('pass' if v <= TOL else 'FAIL', v)

# spinning reserve
v = 0.0
for t in range(T):
    tot = sum(g['reserve_MW'][t] for g in rep['thermal_generators'])
    v = max(v, max(0.0, reserves[t] - tot))
res['spinning_reserve'] = ('pass' if v <= TOL else 'FAIL', v)

# reserve deliverability: r <= ramp_up_limit; p+r <= pmax*u; r=0 if off
v = 0.0
for g in rep['thermal_generators']:
    src = th[g['name']]
    for t in range(T):
        u = g['commitment'][t]
        if g['reserve_MW'][t] < -TOL:
            v = max(v, -g['reserve_MW'][t])
        if g['reserve_MW'][t] > src['ramp_up_limit'] + TOL:
            v = max(v, g['reserve_MW'][t] - src['ramp_up_limit'])
        if g['production_MW'][t] + g['reserve_MW'][t] > src['power_output_maximum'] * u + TOL:
            v = max(v, g['production_MW'][t] + g['reserve_MW'][t] - src['power_output_maximum'] * u)
        if u == 0 and g['reserve_MW'][t] > TOL:
            v = max(v, g['reserve_MW'][t])
res['reserve_deliverability'] = ('pass' if v <= TOL else 'FAIL', v)

# generator limits
v = 0.0
for g in rep['thermal_generators']:
    src = th[g['name']]
    for t in range(T):
        u = g['commitment'][t]
        if g['production_MW'][t] < src['power_output_minimum'] * u - TOL:
            v = max(v, src['power_output_minimum'] * u - g['production_MW'][t])
        if g['production_MW'][t] > src['power_output_maximum'] * u + TOL:
            v = max(v, g['production_MW'][t] - src['power_output_maximum'] * u)
res['generator_limits'] = ('pass' if v <= TOL else 'FAIL', v)

# must-run
bad = []
for g in rep['thermal_generators']:
    if th[g['name']]['must_run']:
        for t in range(T):
            if g['commitment'][t] != 1:
                bad.append((g['name'], t))
res['must_run'] = ('pass' if not bad else 'FAIL', bad[:5])

# ramping (standard UC rows, including startup/shutdown ramps and t=1 vs initial state)
v = 0.0
for g in rep['thermal_generators']:
    src = th[g['name']]
    RU, RD = src['ramp_up_limit'], src['ramp_down_limit']
    SUr, SDr = src['ramp_startup_limit'], src['ramp_shutdown_limit']
    p = g['production_MW']; u = g['commitment']
    y = g['startup']; z = g['shutdown']
    for t in range(T):
        pu = src['power_output_t0'] if t == 0 else p[t - 1]
        uu = src['unit_on_t0'] if t == 0 else u[t - 1]
        up_diff = p[t] - pu
        if up_diff > RU * uu + SUr * y[t] + TOL:
            v = max(v, up_diff - (RU * uu + SUr * y[t]))
        dn_diff = pu - p[t]
        if dn_diff > RD * u[t] + SDr * z[t] + TOL:
            v = max(v, dn_diff - (RD * u[t] + SDr * z[t]))
res['ramping'] = ('pass' if v <= TOL else 'FAIL', v)

# minimum up/down
v = 0
viol = []
for g in rep['thermal_generators']:
    src = th[g['name']]
    mu, md = src['time_up_minimum'], src['time_down_minimum']
    u = g['commitment']; y = g['startup']; z = g['shutdown']
    u0, tup0, tdn0 = src['unit_on_t0'], src['time_up_t0'], src['time_down_t0']
    # initial-condition forced states
    if u0 == 1 and tup0 < mu:
        for t in range(min(mu - tup0, T)):
            if u[t] != 1:
                viol.append(('init-up', g['name'], t))
    if u0 == 0 and tdn0 < md:
        for t in range(min(md - tdn0, T)):
            if u[t] != 0:
                viol.append(('init-down', g['name'], t))
    for t in range(T):
        s = sum(y[tau] for tau in range(max(0, t - mu + 1), t + 1))
        if s > u[t] + TOL:
            viol.append(('up', g['name'], t))
        s = sum(z[tau] for tau in range(max(0, t - md + 1), t + 1))
        if s > 1 - u[t] + TOL:
            viol.append(('down', g['name'], t))
res['minimum_up_down'] = ('pass' if not viol else 'FAIL', viol[:5])

# startup/shutdown logic
bad = []
for g in rep['thermal_generators']:
    src = th[g['name']]
    u = g['commitment']; y = g['startup']; z = g['shutdown']
    for t in range(T):
        prev = src['unit_on_t0'] if t == 0 else u[t - 1]
        if y[t] != int(u[t] == 1 and prev == 0):
            bad.append(('y', g['name'], t))
        if z[t] != int(u[t] == 0 and prev == 1):
            bad.append(('z', g['name'], t))
        if y[t] and z[t]:
            bad.append(('yz', g['name'], t))
res['startup_shutdown_logic'] = ('pass' if not bad else 'FAIL', bad[:5])

# initial conditions: hour-1 startup/shutdown consistent with t0 state (checked above);
# also p at hour 1 vs p0 ramp (covered by ramping with t=0 case)
res['initial_conditions'] = ('pass', 0)

# renewable limits
v = 0.0
for g in rep['renewable_generators']:
    src = rn[g['name']]
    for t in range(T):
        pv = g['production_MW'][t]
        if pv < src['power_output_minimum'][t] - TOL:
            v = max(v, src['power_output_minimum'][t] - pv)
        if pv > src['power_output_maximum'][t] + TOL:
            v = max(v, pv - src['power_output_maximum'][t])
res['renewable_limits'] = ('pass' if v <= TOL else 'FAIL', v)

# cost consistency: recompute production + startup cost from schedule
def prod_cost(src, u, pv):
    if u == 0:
        return 0.0
    pws = src['piecewise_production']
    c = pws[0]['cost']
    rem = pv - pws[0]['mw']
    for a, b in zip(pws[:-1], pws[1:]):
        take = min(rem, b['mw'] - a['mw'])
        c += take * (b['cost'] - a['cost']) / (b['mw'] - a['mw'])
        rem -= take
    return c

def startup_cost(src, Uarr, t):
    if t == 0:
        d = src['time_down_t0'] if src['unit_on_t0'] == 0 else None
    else:
        d = 0; k = t - 1
        while k >= 0 and Uarr[k] == 0:
            d += 1; k -= 1
        if k < 0 and src['unit_on_t0'] == 0:
            d += src['time_down_t0']
    if d is None:
        return 0.0
    tiers = src['startup']
    best = tiers[0]['cost']
    for s in tiers:
        if d >= s['lag']:
            best = s['cost']
    return best

tc = 0.0
sc = 0.0
for g in rep['thermal_generators']:
    src = th[g['name']]
    Uarr = g['commitment']
    for t in range(T):
        tc += prod_cost(src, Uarr[t], g['production_MW'][t])
        if g['startup'][t]:
            sc += startup_cost(src, Uarr, t)
obj = rep['summary']['objective_cost']
diff = abs(obj - (tc + sc))
res['cost_consistency'] = ('pass' if diff <= max(1.0, 1e-3 * abs(obj)) else 'FAIL',
                           {'reported': obj, 'recomputed': tc + sc, 'diff': diff})

ok = True
for k, (st, m) in res.items():
    print(f'{k:28s} {st}  {m}')
    if st != 'pass':
        ok = False
print('ALL PASS' if ok else 'FAILURES PRESENT')
